import { InfoCard } from 'components.js';





export async function Profile(props) {



  const user = await getUser(props.userId);



  // DO NOT DO THIS



  return <InfoCard user={user} />;



```

```


// components.js




"use client";





export async function InfoCard({ user }) {



  return <div>{user.name}</div>;



```

